    LineThickness: 2;
    FontColor: #ffffff;
    FontSize: 24;
    HorizontalAlignment: center;
    Shadowing: 0;
  }
</style>

person "==Customer\n<size:16>[Person]</size>\n\nA customer who browses the catalogue and places orders through the web application" <<Element-RWxlbWVudCxQZXJzb24=>> as Customer
person "==Support Agent\n<size:16>[Person]</size>\n\nA support team member who looks up and amends orders on behalf of customers" <<Element-RWxlbWVudCxQZXJzb24=>> as SupportAgent
rectangle "==Payment Gateway\n<size:16>[Software System]</size>\n\nThird-party service that authorizes and captures card payments" <<Element-RWxlbWVudCxTb2Z0d2FyZSBTeXN0ZW0sRXh0ZXJuYWw=>> as PaymentGateway

rectangle "Order Service\n<size:16>[Software System]</size>" <<Boundary-T3JkZXIgU2VydmljZQ==>> {
  rectangle "==Web Application\n<size:16>[Container: TypeScript/React]</size>\n\nServer-rendered UI for browsing the catalogue and placing orders" <<Element-RWxlbWVudCxDb250YWluZXIsV2Vi>> as OrderService.WebApplication
  rectangle "==Order API\n<size:16>[Container: Java/Spring Boot]</size>\n\nREST API that validates, persists and prices orders" <<Element-RWxlbWVudCxDb250YWluZXI=>> as OrderService.OrderAPI
  database "==Order Database\n<size:16>[Container: PostgreSQL 16]</size>\n\nSystem of record for orders and order items" <<Element-RWxlbWVudCxDb250YWluZXIsRGF0YWJhc2U=>> as OrderService.OrderDatabase
  queue "==Message Queue\n<size:16>[Container: RabbitMQ]</size>\n\nBuffers order events for asynchronous processing" <<Element-RWxlbWVudCxDb250YWluZXIsUXVldWU=>> as OrderService.MessageQueue
  person "==Order Worker\n<size:16>[Container: Java/Spring Boot]</size>\n\nConsumes order events and updates order status" <<Element-RWxlbWVudCxDb250YWluZXIsV29ya2Vy>> as OrderService.OrderWorker
}

Customer --> OrderService.WebApplication <<Relationship-UmVsYXRpb25zaGlw>> : "places orders through\n<size:16>[HTTPS]</size>"
SupportAgent --> OrderService.WebApplication <<Relationship-UmVsYXRpb25zaGlw>> : "looks up and amends orders through\n<size:16>[HTTPS]</size>"
OrderService.WebApplication --> OrderService.OrderAPI <<Relationship-UmVsYXRpb25zaGlw>> : "calls\n<size:16>[HTTPS/JSON]</size>"
OrderService.OrderAPI --> OrderService.OrderDatabase <<Relationship-UmVsYXRpb25zaGlw>> : "reads from and writes to\n<size:16>[JDBC/SQL]</size>"
OrderService.OrderAPI --> OrderService.MessageQueue <<Relationship-UmVsYXRpb25zaGlwLEFzeW5j>> : "publishes order events to\n<size:16>[AMQP]</size>"
OrderService.OrderWorker --> OrderService.MessageQueue <<Relationship-UmVsYXRpb25zaGlwLEFzeW5j>> : "consumes order events from\n<size:16>[AMQP]</size>"
OrderService.OrderWorker --> OrderService.OrderDatabase <<Relationship-UmVsYXRpb25zaGlw>> : "updates order status in\n<size:16>[JDBC/SQL]</size>"
OrderService.OrderAPI --> PaymentGateway <<Relationship-UmVsYXRpb25zaGlw>> : "authorizes and captures payments via\n<size:16>[HTTPS/JSON]</size>"

@enduml",

